import type { Feature, FeatureCollection } from "geojson";

import { RISK_GRID } from "@/data/risk-grid";

/** A cell from the Kabylie fire-risk priority map (generated by ml/fire-risk). */
export interface RiskPoint {
  id: string;
  lat: number;
  lng: number;
  /**
   * Relative rank 0-1: the share of the mapped land that scores lower.
   * 0.9 means riskier than 90% of the land. NOT a probability of fire.
   */
  risk: number;
}

/** Band cut-offs on the rank: High = top 10% of land, Medium = next 20%. */
export const RISK_BAND_HIGH = 0.9;
export const RISK_BAND_MEDIUM = 0.7;

export type RiskBand = "high" | "medium" | "low";

export function riskBand(rank: number): RiskBand {
  if (rank >= RISK_BAND_HIGH) return "high";
  if (rank >= RISK_BAND_MEDIUM) return "medium";
  return "low";
}

/** "Top N%" of the land this cell belongs to (1-100). */
export function riskTopShare(rank: number): number {
  return Math.min(100, Math.max(1, Math.round((1 - rank) * 100)));
}

export const RISK_POINTS: RiskPoint[] = RISK_GRID.map(([lng, lat, risk]) => ({
  id: `${lng},${lat}`,
  lat,
  lng,
  risk,
}));

export function riskGeoJSON(): FeatureCollection {
  const features: Feature[] = RISK_POINTS.map((p) => ({
    type: "Feature",
    id: p.id,
    properties: { kind: "risk", id: p.id, risk: p.risk },
    geometry: { type: "Point", coordinates: [p.lng, p.lat] },
  }));
  return { type: "FeatureCollection", features };
}
